import {FunctionComponent, ComponentChildren } from 'preact';

import styles from './styles.module.scss';

const CLASSES_BY_VARIANT = {
  primary: 'fBtnPrimary',
  secondary: 'fBtnSecondary',
  link: 'fBtnLink',
};

interface Props {
  variant: 'primary' | 'secondary' | 'link';
  type?: 'button' | 'submit';
  size?: 'medium' | 'large';
  className?: string;
  children: ComponentChildren,
  onClick?: (evt: MouseEvent) => void;
  disabled?: boolean;
  style?: any;
}

const Button: FunctionComponent<Props> = ({ type = 'button', variant, size = 'medium', children, className, ...props }: Props) => (
  <button
    type={type}
    {...props}
    className={`${styles.fBtn} ${styles[size]} ${
      styles[CLASSES_BY_VARIANT[variant]]
    } ${className || ''}`}
  >
    {children}
  </button>
);

Button.defaultProps = {
  className: '',
  type: 'button',
  size: 'medium',
};

export default Button;
