import { useDispatch } from 'react-redux';
import { FunctionComponent } from 'preact';

import DeleteOutlineIcon from '@material-ui/icons/DeleteOutline';

import Popover from '../../../../../../shared/Popover';
import { deleteFriend } from '../../../../slice/thunks';

import styles from './styles.module.scss';
import { UserDb } from '../../../../../user/slice/types';

interface Props {
  friend: UserDb;
  onClose: (evt: MouseEvent) => unknown;
}

const MorePopover: FunctionComponent<Props> = ({ friend, onClose }: Props) => {
  const dispatch = useDispatch();
  /*
  const handleHide = () => {
    // Mute forever
    console.log('handleHide');
  };

  const handleMute = () => {
    // mute for 1 day
    console.log('handleMute');
  };
  */

  const handleRemove = async () => {
    const result = window.confirm(
      `Are you sure you want to remove ${friend.name}`
    );

    if (!result) return null;

    try {
      // eslint-disable-next-line @typescript-eslint/await-thenable
      await dispatch(deleteFriend(friend.id));
    } catch (e) {
      console.error('handleRemove', e);
      window.alert(
        `There was an error when removing ${friend.name}. Try again later.`
      );
    }
  };

  return (
    <Popover onClose={onClose} className={styles.morePopover}>
      <>
        {/*<button className="listButton" onClick={handleHide}>*/}
        {/*  <VisibilityOffIcon />*/}

        {/*  <div>*/}
        {/*    <b className="btnTitle">Hide {friend.name}</b>*/}
        {/*    <p className="btnSubtitle">*/}
        {/*      You won&apos;t see {friend.name} but stay friends.*/}
        {/*    </p>*/}
        {/*  </div>*/}
        {/*</button>*/}

        {/*<button className="listButton" onClick={handleMute}>*/}
        {/*  <VolumeMuteIcon />*/}

        {/*  <div>*/}
        {/*    <b className="btnTitle">Mute {friend.name} for 1 day</b>*/}
        {/*    <p className="btnSubtitle">*/}
        {/*      Stop receiving GIFs from {friend.name}.*/}
        {/*    </p>*/}
        {/*  </div>*/}
        {/*</button>*/}

        <button className={styles.listButton} onClick={handleRemove}>
          <DeleteOutlineIcon className={styles.deleteIcon} />

          <div>
            <b className={styles.btnTitle}>Remove {friend.name}</b>
            <p className={styles.btnSubtitle}>
              Permanently delete {friend.name}.
            </p>
          </div>
        </button>
      </>
    </Popover>
  );
};

export default MorePopover;
