import { useState } from 'preact/hooks';
import PropTypes from 'prop-types';

import { useDispatch, useSelector } from 'react-redux';

import StateIndicator from '../../../../../../shared/StateIndicator';
import { updateUser } from '../../../../../user/slice';
import { selectLoggedUser } from '../../../../../user/slice';

import { timeInMs } from '../../../../../../../shared';
import Button from '../../../../../../shared/Button';

import styles from './styles.module.scss';
import { FunctionComponent } from 'preact';

interface Props {
  mutedMessagesUntil: number;
  onSubmit: () => unknown,
  onBack: () => unknown,
}

const CurrentlyDisabled: FunctionComponent<Props> = ({ mutedMessagesUntil, onSubmit, onBack }: Props) => (
  <div>
    <div className={styles.nestedContent}>
      <p>
        GIFs disabled until{' '}
        <b>
          {mutedMessagesUntil === -1
            ? 'Forever'
            : new Date(mutedMessagesUntil).toLocaleTimeString([], {
              year: 'numeric',
              month: 'numeric',
              day: 'numeric',
              hour: '2-digit',
              minute: '2-digit',
            })}
        </b>
      </p>
    </div>

    <div className={styles.buttonsFooter}>
      <Button variant="primary" onClick={onSubmit}>
        Enable again
      </Button>
      <Button variant="link" onClick={onBack}>
        Cancel
      </Button>
    </div>
  </div>
);

// -----------------------------------------------------------------------------

const DISABLE_OPTIONS = {
  [timeInMs.hour]: '1 Hour',
  [timeInMs.week]: '1 Week',
  [timeInMs.month]: '1 Month',
  '-1': 'Forever',
};

const DisableForm = ({ onBack, onSubmit }) => {
  const list = [timeInMs.hour, timeInMs.week, timeInMs.month, -1];
  const [selected, setSelected] = useState(list[0]);

  const handleSubmit = (e) => {
    e.preventDefault();
    onSubmit(selected);
  };

  const handleChange = (evt) => {
    setSelected(Number(evt.target.value));
  };

  return (
    <div>
      <div className={styles.nestedContent}>
        <p>Disable the sending and receiving of GIF messages for...</p>
      </div>

      <form onSubmit={handleSubmit}>
        <div className={styles.nestedContent}>
          {list.map((value) => (
            <label key={value} className={styles.radioLabel}>
              <input
                type="radio"
                value={value}
                checked={value === selected}
                onChange={handleChange}
              />
              {DISABLE_OPTIONS[value]}
            </label>
          ))}
        </div>

        <div className={styles.buttonsFooter}>
          <Button type="submit" variant="primary">
            Disable
          </Button>
          <Button variant="link" onClick={onBack}>
            Cancel
          </Button>
        </div>
      </form>
    </div>
  );
};

DisableForm.propTypes = {
  onSubmit: PropTypes.func.isRequired,
  onBack: PropTypes.func.isRequired,
};

interface DisableGifsProps {
  changeView: () => unknown;
}

// All the functionality here
const DisableGifs: FunctionComponent<DisableGifsProps> = ({ changeView }: DisableGifsProps) => {
  const dispatch = useDispatch();
  const [isLoading, setLoading] = useState(false);
  const user = useSelector(selectLoggedUser);

  const handleRequest = async (mutedMessagesUntil) => {
    setLoading(true);
    try {
      // console.log('handleDisable', mutedMessagesUntil);
      // eslint-disable-next-line @typescript-eslint/await-thenable
      await dispatch(updateUser({ mutedMessagesUntil }));
    } catch (err) {
      window.alert(`There was an error. Please try again later`);
      console.error('handleDisable', err);
    }

    setLoading(false);
  };

  const handleEnable = () => {
    handleRequest(null);
  };

  const handleDisable = (mutedMessagesUntil) => {
    handleRequest(
      mutedMessagesUntil === -1
        ? mutedMessagesUntil
        : Date.now() + mutedMessagesUntil
    );
  };

  if (isLoading) return <StateIndicator type="loading" />;

  const goBack = () => changeView();

  const isDisabled =
    user.mutedMessagesUntil === -1 ||
    (user.mutedMessagesUntil || 0) > Date.now();

  if (isDisabled) {
    return (
      <CurrentlyDisabled
        mutedMessagesUntil={user.mutedMessagesUntil}
        onSubmit={handleEnable}
        onBack={goBack}
      />
    );
  }

  return <DisableForm onBack={goBack} onSubmit={handleDisable} />;
};

export default DisableGifs;
